// ---------------------------------------------------------------------
// Filtre 1D. 'in' et 'out' peuvent être le même tableau.
//   deriv = false : lissage     f(x)  = k (alpha|x| + 1) e^{-alpha|x|}   (gain DC = 1)
//   deriv = true  : dérivée     f'(x) = -k' x e^{-alpha|x|}              (rampe unité -> 1)
// Les bords sont gérés par recopie du premier/dernier échantillon.
// ---------------------------------------------------------------------


template <class Type> void deriche1D(const Type* in, Type* out, int n, double alpha, bool deriv)
{
    if (n <= 0) return;
    const double r  = std::exp(-alpha);
    const double r2 = r * r;

    // Marge de recopie : la transitoire décroît en e^{-alpha*i}
    const int pad = std::max(4, (int)std::ceil(12.0 / alpha));
    const int m   = n + 2 * pad;

    std::vector<double> p(m), yp(m, 0.0), ym(m, 0.0);
    for (int i = 0; i < m; ++i) {
        int j = std::min(std::max(i - pad, 0), n - 1);
        p[i] = in[j];
    }

    auto X = [&](int i) { return (i >= 0 && i < m) ? p[i] : 0.0; };

    if (!deriv) {
        const double k = (1 - r) * (1 - r) / (1 + 2 * alpha * r - r2);
        const double a1 = k,            a2 = k * r * (alpha - 1);   // causal
        const double b1 = k * r * (alpha + 1), b2 = -k * r2;       // anti-causal

        for (int i = 0; i < m; ++i) {                    // passe avant
            double y1 = i >= 1 ? yp[i - 1] : 0.0;
            double y2 = i >= 2 ? yp[i - 2] : 0.0;
            yp[i] = a1 * X(i) + a2 * X(i - 1) + 2 * r * y1 - r2 * y2;
        }
        for (int i = m - 1; i >= 0; --i) {               // passe arrière
            double y1 = i + 1 < m ? ym[i + 1] : 0.0;
            double y2 = i + 2 < m ? ym[i + 2] : 0.0;
            ym[i] = b1 * X(i + 1) + b2 * X(i + 2) + 2 * r * y1 - r2 * y2;
        }
    } else {
        // Normalisation : une rampe x[n]=n donne une dérivée de 1
        const double k = (1 - r) * (1 - r) * (1 - r) / (2 * r * (1 + r));
        const double a = -k * r;   // causal      : coefficient de x[n-1]
        const double b =  k * r;   // anti-causal : coefficient de x[n+1]

        for (int i = 0; i < m; ++i) {
            double y1 = i >= 1 ? yp[i - 1] : 0.0;
            double y2 = i >= 2 ? yp[i - 2] : 0.0;
            yp[i] = a * X(i - 1) + 2 * r * y1 - r2 * y2;
        }
        for (int i = m - 1; i >= 0; --i) {
            double y1 = i + 1 < m ? ym[i + 1] : 0.0;
            double y2 = i + 2 < m ? ym[i + 2] : 0.0;
            ym[i] = b * X(i + 1) + 2 * r * y1 - r2 * y2;
        }
    }

    for (int i = 0; i < n; ++i) out[i] = yp[i + pad] + ym[i + pad];
}

// ---------------------------------------------------------------------
// Image 2D (stockage ligne par ligne) et filtrage séparable
// ---------------------------------------------------------------------
struct Image {
    int w = 0, h = 0;
    std::vector<double> d;
    Image(int w_, int h_) : w(w_), h(h_), d((size_t)w_ * h_, 0.0) {}
    double& at(int x, int y) { return d[(size_t)y * w + x]; }
    double  at(int x, int y) const { return d[(size_t)y * w + x]; }
};

// Applique le filtre selon X (derivX) puis selon Y (derivY)
Image dericheFilter2D(const Image& src, double alpha, bool derivX, bool derivY)
{
    Image tmp = src;
    for (int y = 0; y < tmp.h; ++y)                      // lignes
        deriche1D(&tmp.d[(size_t)y * tmp.w], &tmp.d[(size_t)y * tmp.w], tmp.w, alpha, derivX);

    std::vector<double> col(tmp.h);
    for (int x = 0; x < tmp.w; ++x) {                    // colonnes
        for (int y = 0; y < tmp.h; ++y) col[y] = tmp.at(x, y);
        deriche1D(col.data(), col.data(), tmp.h, alpha, derivY);
        for (int y = 0; y < tmp.h; ++y) tmp.at(x, y) = col[y];
    }
    return tmp;
}

// Gradient de Deriche : dérivée selon un axe, lissage selon l'autre
void dericheGradient(const Image& src, double alpha, Image& gx, Image& gy, Image& mag)
{
    gx = dericheFilter2D(src, alpha, true,  false);
    gy = dericheFilter2D(src, alpha, false, true);
    mag = Image(src.w, src.h);
    for (size_t i = 0; i < mag.d.size(); ++i)
        mag.d[i] = std::hypot(gx.d[i], gy.d[i]);
}



